// ── Shared dataset ─────────────────────────────────────────────────────────
// Both grids receive the SAME array instance shape, generated by the SAME
// code, before either grid mounts. Generation is deterministic (no
// Math.random) so every run — and every grid — sees byte-identical input.
// This must never be called inside a measured window.

import { DEFAULT_COLUMN_COUNT, extraField } from './shared-config'

export interface Row {
  id: number
  name: string
  department: string
  salary: number
  location: string
  active: boolean
  joinDate: string
  score: number
  // Synthetic fields for the column axis — `extra0`, `extra1`, … Present only
  // when the run asks for more than the eight base columns.
  [extra: string]: string | number | boolean
}

const departments = ['Engineering', 'Design', 'Marketing', 'HR', 'Finance']
const locations = ['New York', 'San Francisco', 'Austin', 'Chicago', 'Boston']

/**
 * @param count       rows to generate
 * @param columnCount total columns the run will render. Anything above the
 *                    eight base fields adds an `extraN` value per row, so a
 *                    wide grid has real data in every cell rather than blanks
 *                    — a blank cell is cheap to render and would flatter both
 *                    libraries at exactly the size the axis exists to measure.
 */
export function generateData(
  count: number,
  columnCount: number = DEFAULT_COLUMN_COUNT
): Row[] {
  const rows: Row[] = new Array<Row>(count)
  const joinBase = Date.UTC(2010, 0, 1)
  const joinRange = Date.UTC(2024, 0, 1) - joinBase
  const extraCount = Math.max(0, columnCount - DEFAULT_COLUMN_COUNT)

  for (let i = 0; i < count; i++) {
    const joinMs = joinBase + ((i * 7_919) % joinRange)
    rows[i] = {
      id: i + 1,
      // Scrambled so sorting by name is real work, not a no-op on
      // already-ordered data.
      name: `Employee ${((i * 2_654_435_761) % count) + 1}`,
      department: departments[i % departments.length]!,
      salary: 50_000 + ((i * 7_919) % 150_000),
      location: locations[i % locations.length]!,
      active: i % 3 !== 0,
      joinDate: new Date(joinMs).toISOString().slice(0, 10),
      score: (i * 4_099) % 1000,
    }

    // Deterministic like everything else here, and varied per column so no
    // grid can benefit from repeated identical values.
    for (let c = 0; c < extraCount; c++) {
      rows[i]![extraField(c)] = (i * 7_919 + c * 104_729) % 100_000
    }
  }
  return rows
}
